const listEffectiveCarrierClauses = `-- name: ListEffectiveCarrierClauses :many

SELECT c.id AS clause_id, c.slug, c.title, c.status AS clause_status,
       cb.conditions, cb.since_clause_version,
       cv.version, cv.content, cv.content_sha256
FROM clause_binding cb
JOIN clause c ON c.id = cb.clause_id AND c.status = 'active'
JOIN LATERAL (
    SELECT v.version, v.content, v.content_sha256
    FROM clause_version v
    WHERE v.clause_id = cb.clause_id
    ORDER BY v.version DESC
    LIMIT 1
) cv ON TRUE
WHERE cb.scope = $1::text
  AND cb.scope_id = $2::uuid
  AND cb.status = 'active'
  AND (
    cb.conditions IS NULL
    OR cb.conditions->'task_kinds' IS NULL
    OR jsonb_typeof(cb.conditions->'task_kinds') <> 'array'
    OR $3::text IN (SELECT jsonb_array_elements_text(cb.conditions->'task_kinds'))
  )
ORDER BY c.slug
`

type ListEffectiveCarrierClausesParams struct {
	Scope    string      `json:"scope"`
	ScopeID  pgtype.UUID `json:"scope_id"`
	TaskKind string      `json:"task_kind"`
}

type ListEffectiveCarrierClausesRow struct {
	ClauseID           pgtype.UUID `json:"clause_id"`
	Slug               string      `json:"slug"`
	Title              string      `json:"title"`
	ClauseStatus       string      `json:"clause_status"`
	Conditions         []byte      `json:"conditions"`
	SinceClauseVersion int32       `json:"since_clause_version"`
	Version            int32       `json:"version"`
	Content            string      `json:"content"`
	ContentSha256      string      `json:"content_sha256"`
}

// ── Effective Clause Set (claim hot path) ─────────────────────────────────
// The point query per carrier: active bindings of this carrier entity whose
// conditions admit the task kind (NULL conditions / missing task_kinds key =
// unconditional), joined to the clause and its newest version. Deterministic
// order: slug. Same input → same rows, same order (ADR 007 §5).
func (q *Queries) ListEffectiveCarrierClauses(ctx context.Context, arg ListEffectiveCarrierClausesParams) ([]ListEffectiveCarrierClausesRow, error) {
	rows, err := q.db.Query(ctx, listEffectiveCarrierClauses, arg.Scope, arg.ScopeID, arg.TaskKind)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListEffectiveCarrierClausesRow{}
	for rows.Next() {
		var i ListEffectiveCarrierClausesRow
		if err := rows.Scan(
			&i.ClauseID,
			&i.Slug,
			&i.Title,
			&i.ClauseStatus,
			&i.Conditions,
			&i.SinceClauseVersion,
			&i.Version,
			&i.Content,
			&i.ContentSha256,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

